INSERT INTO requirement VALUES ('OSHA-HAZCOM-001', 'The employer shall develop, implement, and maintain at each workplace a written hazard communication program describing how labels, safety data sheets, and employee training requirements will be met, including a list of hazardous chemicals present.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(e)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(e)(1)', 'Employers shall develop, implement, and maintain at each workplace, a written hazard communication program which at least describes how the criteria specified in paragraphs (f), (g), and (h) of this section for labels and other forms of warning, safety data sheets, and employee information and training will be met.', '2024-07-01', '2026-05-04T00:00:00Z', '1cf8e95ee0d69e828ada2ea0697fd2852cdcf180f29853be5a74e950725ddaf4', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-002', 'The written hazard communication program shall include a list of the hazardous chemicals known to be present using a product identifier referenced on the appropriate safety data sheet.', TRUE, 'obligation', 'medium', 'document_review', 'written_program', 'chemical_procurement', '{}', 'all_covered_industries', '', '', 'chemical_handling|material_storage', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(e)(1)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(e)(1)(i)', 'A list of the hazardous chemicals known to be present using a product identifier that is referenced on the appropriate safety data sheet (the list may be compiled for the workplace as a whole or for individual work areas).', '2024-07-01', '2026-05-04T00:00:00Z', 'f97a33e68b4e035fb58d88b33c7fb8a1eaae24171596681f808417b28f6c1b03', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-003', 'The chemical manufacturer, importer, or distributor shall ensure that each container of hazardous chemicals leaving the workplace is labeled with the product identifier, signal word, hazard statement, pictogram, precautionary statement, and supplier information.', TRUE, 'obligation', 'high', 'physical_inspection', 'physical_condition', 'chemical_procurement', '{}', 'all_covered_industries', '', '', 'chemical_handling|material_storage', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(f)(1)', '§1910.1200(f)(1)(i)|§1910.1200(f)(1)(ii)|§1910.1200(f)(1)(iii)|§1910.1200(f)(1)(iv)|§1910.1200(f)(1)(v)|§1910.1200(f)(1)(vi)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(f)(1)', 'The chemical manufacturer, importer, or distributor shall ensure that each container of hazardous chemicals leaving the workplace is labeled, tagged, or marked.', '2024-07-01', '2026-05-04T00:00:00Z', '3401046d0a18e395c4555e7a39f60fb2956281fd50acf1e53b15cc4d2ab2e8bb', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-004', 'Except as provided for alternative written materials under §1910.1200(f)(7) and portable containers for immediate use under §1910.1200(f)(8), the employer shall ensure that each workplace container of hazardous chemicals is labeled with either the information required for shipped-container labels or a product identifier and words, pictures, symbols, or a combination providing general hazard information.', TRUE, 'obligation', 'high', 'physical_inspection', 'physical_condition', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling|material_storage', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(f)(6)', '§1910.1200(f)(6)(i)|§1910.1200(f)(6)(ii)|§1910.1200(f)(7)|§1910.1200(f)(8)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(f)(6)', 'the employer shall ensure that each container of hazardous chemicals in the workplace is labeled, tagged, or marked.', '2024-07-01', '2026-05-04T00:00:00Z', '641db551088c108652c447277596cf23889b92fdc56e444f76c316f0d64787dd', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-005', 'The employer shall have a safety data sheet in the workplace for each hazardous chemical which they use.', TRUE, 'obligation', 'high', 'record_review', 'safety_data_sheet', 'chemical_procurement', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(g)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(g)(1)', 'Employers shall have a safety data sheet in the workplace for each hazardous chemical which they use.', '2024-07-01', '2026-05-04T00:00:00Z', 'db89d7dda471607e9c2b5d924a560dfe52c0de3d82e0b591acee3dbbc42282f9', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-006', 'The employer shall maintain safety data sheets and ensure they are readily accessible during each work shift to employees when they are in their work areas.', TRUE, 'obligation', 'high', 'physical_inspection', 'written_program', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(g)(8)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(g)(8)', 'The employer shall maintain in the workplace copies of the required safety data sheets for each hazardous chemical, and shall ensure that they are readily accessible during each work shift to employees when they are in their work area(s). (Electronic access and other alternatives to maintaining paper copies of the safety data sheets are permitted as long as no barriers to immediate employee access in each workplace are created by such options.)', '2024-07-01', '2026-09-26T00:00:00Z', '722a82de382c6c8b10691c6068dcc3a5231afacc25f5e89f9b5ae17d138b01b4', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-007', 'The employer shall provide employees with effective information and training on hazardous chemicals in their work area at initial assignment and whenever a new chemical hazard about which the employees have not previously been trained is introduced into their work area.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(h)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(h)(1)', 'Employers shall provide employees with effective information and training on hazardous chemicals in their work area at the time of their initial assignment, and whenever a new chemical hazard the employees have not previously been trained about is introduced into their work area.', '2024-07-01', '2026-05-04T00:00:00Z', 'fd7d0bd20664d417cb87072f7aa9a560043f9fbf5e2aa8a810b2a127b962af87', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-008', 'Employees shall be informed of the requirements of the hazard communication standard, operations where hazardous chemicals are present, and the location and availability of the written hazard communication program, including the required hazardous-chemical lists and safety data sheets.', TRUE, 'obligation', 'medium', 'interview', 'training_record', 'onboarding_new_employee', '{"additional_triggers": ["chemical_procurement"], "condition": "A new chemical hazard is introduced into the work area."}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(h)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(h)(2)', 'Employees shall be informed of: The requirements of this section; Any operations in their work area where hazardous chemicals are present; and, The location and availability of the written hazard communication program.', '2024-07-01', '2026-05-04T00:00:00Z', '4b15da4e8fe9a67b4b3c310d2ea7768dcbb5176246620918a758e4675386f1bd', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-009', 'Chemical manufacturers and importers shall evaluate chemicals produced in their workplaces or imported by them to classify the chemicals in accordance with this section.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'chemical_procurement', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(d)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(d)(1)', 'Chemical manufacturers and importers shall evaluate chemicals produced in their workplaces or imported by them to classify the chemicals in accordance with this section. For each chemical, the chemical manufacturer or importer shall determine the hazard classes, and where appropriate, the category of each class that apply to the chemical being classified.', '2024-07-01', '2026-06-13T00:00:00Z', '5eb2834d570eb87c81106782591a87aebc9104c76c1a8ff7d39a9aa60446a4e7', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-010', 'Employers at multi-employer workplaces shall include in their hazard communication program the methods for providing other employers with on-site access to safety data sheets and informing them of precautionary measures and the labeling system used.', TRUE, 'obligation', 'medium', 'document_review', 'written_program', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(e)(2)', '§1910.1200(e)(2)(i)|§1910.1200(e)(2)(ii)|§1910.1200(e)(2)(iii)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(e)(2)', 'Employers who produce, use, or store hazardous chemicals at a workplace in such a way that the employees of other employer(s) may be exposed shall additionally ensure that the hazard communication programs developed and implemented under this paragraph (e) include the methods the employer will use to provide the other employer(s) on-site access to safety data sheets for each hazardous chemical.', '2024-07-01', '2026-06-13T00:00:00Z', '05bc20e7b993d8edaa9d73773af4f3c67655cf5bb92008343b0ba3b370ec8c22', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-011', 'The employer shall make the written hazard communication program available, upon request, to employees, their designated representatives, and OSHA officials.', TRUE, 'obligation', 'low', 'document_review', 'written_program', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(e)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(e)(4)', 'The employer shall make the written hazard communication program available, upon request, to employees, their designated representatives, the Assistant Secretary and the Director, in accordance with the requirements of 29 CFR 1910.1020(e).', '2024-07-01', '2026-06-13T00:00:00Z', 'c49da858bb15f082646fbe4f7e8e9281a81251243fd2f2eea50bb143bc882b5f', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-012', 'The employer may use signs, placards, process sheets, batch tickets, or other written materials in lieu of affixing labels to individual stationary process containers, provided the alternative method identifies the containers and conveys the required label information.', FALSE, 'permission', 'low', 'physical_inspection', 'procedure', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling|material_storage', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(f)(7)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(f)(7)', 'The employer may use signs, placards, process sheets, batch tickets, operating procedures, or other such written materials in lieu of affixing labels to individual stationary process containers, as long as the alternative method identifies the containers to which it is applicable and conveys the information required by paragraph (f)(6) of this section.', '2024-07-01', '2026-06-13T00:00:00Z', 'e78982d2e81cf8c6f6cf023c72a1c3519b20c82f560026d0fad066b27db4a488', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-013', 'The employer is not required to label portable containers into which hazardous chemicals are transferred from labeled containers and which are intended only for the immediate use of the employee who performs the transfer.', FALSE, 'permission', 'low', 'observation', 'physical_condition', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(f)(8)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(f)(8)', 'The employer is not required to label portable containers into which hazardous chemicals are transferred from labeled containers, and which are intended only for the immediate use of the employee who performs the transfer.', '2024-07-01', '2026-06-13T00:00:00Z', 'acf8515622a31099c2f69ceae6a421fa5ecf4e321f11e11df9901de37f3d127a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-014', 'The employer shall not remove or deface existing labels on incoming containers of hazardous chemicals unless the container is immediately marked with the required information.', TRUE, 'prohibition', 'high', 'physical_inspection', 'physical_condition', 'always_on', '{}', 'all_covered_industries', '', '', 'chemical_handling|material_storage', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(f)(9)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(f)(9)', 'The employer shall not remove or deface existing labels on incoming containers of hazardous chemicals, unless the container is immediately marked with the required information.', '2024-07-01', '2026-06-13T00:00:00Z', '7e3c26d44c29a4a43fe4c02a34f29b9f684c0b0f706ed7e101df1581cb8ab3e1', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-015', 'The chemical manufacturer, importer, or employer preparing the safety data sheet shall ensure that significant new hazard or protective-measure information is added to the safety data sheet within three months.', TRUE, 'obligation', 'medium', 'record_review', 'written_program', 'regulatory_update', '{}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(g)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(g)(5)', 'Requires updating: if the chemical manufacturer, importer or employer preparing the safety data sheet becomes newly aware of any significant information regarding the hazards of a chemical, or ways to protect against the hazards, this new information shall be added to the safety data sheet within three months.', '2024-07-01', '2026-09-26T00:00:00Z', '5d72c0f49ad7fb806a37b6af80badc98af6e740b5adcb55eaccde6db59b350d1', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-HAZCOM-016', 'Employee training shall include methods to detect the presence or release of a hazardous chemical, the physical and health hazards of chemicals in the work area, protective measures, and the details of the employer''s hazard communication program.', TRUE, 'obligation', 'high', 'interview', 'training_record', 'onboarding_new_employee', '{"additional_triggers": ["chemical_procurement"], "condition": "A new chemical hazard is introduced into the work area."}', 'all_covered_industries', '', '', 'chemical_handling', 'any', 'federal', 'OSHA_HAZCOM', '§1910.1200(h)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.1200#p-1910.1200(h)(3)', 'Employee training shall include at least:
(i) Methods and observations that may be used to detect the presence or release of a hazardous chemical in the work area (such as monitoring conducted by the employer, continuous monitoring devices, visual appearance or odor of hazardous chemicals when being released, etc.)
(ii) The physical, health, simple asphyxiation, combustible dust, and pyrophoric gas hazards, as well as hazards not otherwise classified, of the chemicals in the work area
(iii) The measures employees can take to protect themselves from these hazards, including specific procedures the employer has implemented to protect employees from exposure to hazardous chemicals, such as appropriate work practices, emergency procedures, and personal protective equipment to be used
(iv) The details of the hazard communication program developed by the employer, including an explanation of the labels received on shipped containers and the workplace labeling system used by their employer; the safety data sheet, including the order of information and how employees can obtain and use the appropriate hazard information', '2024-07-01', '2026-09-26T00:00:00Z', 'c424fe8ceb53b2b70598f95eee10af028542d1cabe5fb0c3e76cdcf9139a9661', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-21', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-001', 'The employer shall establish an energy control program consisting of procedures, employee training, and periodic inspections to ensure isolation before servicing or maintenance where unexpected energization, start-up, or release of stored energy could occur and cause injury.', TRUE, 'obligation', 'critical', 'document_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(1)', 'The employer shall establish a program consisting of energy control procedures, employee training and periodic inspections to ensure that before any employee performs any servicing or maintenance on a machine or equipment where the unexpected energizing, startup or release of stored energy could occur and cause injury, the machine or equipment shall be isolated from the energy source and rendered inoperative.', '2024-07-01', '2026-06-13T00:00:00Z', 'b8830682901a389e56c3bd70b601f4e9b68a3c18f459521ec0c26a799df4bf43', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-002', 'Procedures shall be developed, documented, and utilized for the control of potentially hazardous energy when employees are engaged in covered servicing or maintenance activities.', TRUE, 'obligation', 'critical', 'document_review', 'procedure', 'equipment_change', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(4)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(4)(i)', 'Procedures shall be developed, documented and utilized for the control of potentially hazardous energy when employees are engaged in the activities covered by this section.', '2024-07-01', '2026-06-13T00:00:00Z', 'a467cb6f8ba32a190103cb624ee5b9e77f61ca1c116044abaa326317f04ead7a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-003', 'The energy control procedures shall clearly and specifically outline the scope, purpose, authorization, rules, and techniques to be utilized for the control of hazardous energy, and the means to enforce compliance.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'equipment_change', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(4)(ii)', '§1910.147(c)(4)(ii)(A)|§1910.147(c)(4)(ii)(B)|§1910.147(c)(4)(ii)(C)|§1910.147(c)(4)(ii)(D)|§1910.147(c)(4)(ii)(E)|§1910.147(c)(4)(ii)(F)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(4)(ii)', 'The procedures shall clearly and specifically outline the scope, purpose, authorization, rules, and techniques to be utilized for the control of hazardous energy, and the means to enforce compliance.', '2024-07-01', '2026-06-13T00:00:00Z', '1da9cbe125f7fb933c6b257fc21a1e65255d8030e9d8be7138b8b2dcc7f2c9a8', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-004', 'The employer shall provide locks, tags, chains, wedges, key blocks, adapter pins, self-locking fasteners, or other hardware for isolating, securing, or blocking machines from energy sources.', TRUE, 'obligation', 'high', 'physical_inspection', 'physical_condition', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(5)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(5)(i)', 'Locks, tags, chains, wedges, key blocks, adapter pins, self-locking fasteners, or other hardware shall be provided by the employer for isolating, securing or blocking of machines or equipment from energy sources.', '2024-07-01', '2026-06-13T00:00:00Z', '9077e671cd89e2781bf1a97ed20d2105f6900fa2fd92a6291eb0603961cc9119', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-005', 'The employer shall conduct a periodic inspection of the energy control procedure at least annually to ensure that the procedure and the requirements of this standard are being followed.', TRUE, 'obligation', 'high', 'record_review', 'inspection_record', 'annual_review', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(6)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(6)(i)', 'The employer shall conduct a periodic inspection of the energy control procedure at least annually to ensure that the procedure and the requirements of this standard are being followed.', '2024-07-01', '2026-06-13T00:00:00Z', '6beaa0d404d1d95f102d5cbc8fd86cfd8a533da77072d1a0c1fe0b0f6cf93504', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-006', 'The employer shall provide training to ensure that the purpose and function of the energy control program are understood by employees and that employees acquire the knowledge and skills required for safe application, usage, and removal of energy controls.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(7)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(7)(i)', 'The employer shall provide training to ensure that the purpose and function of the energy control program are understood by employees and that the knowledge and skills required for the safe application, usage, and removal of the energy controls are acquired by employees.', '2024-07-01', '2026-06-13T00:00:00Z', '9872e5c16b68275cb1dbf08eebdcce28a2c425d9b915ab924b1efca2b16f625c', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-007', 'Retraining shall be provided for all authorized and affected employees whenever there is a change in job assignments, machines, equipment, or processes that present a new hazard, or a change in energy control procedures.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'equipment_change', '{"additional_triggers": ["job_reassignment", "procedure_change"], "condition": "Retraining is required after job reassignment, a machine/equipment/process change presenting a new hazard, or a change in energy-control procedures."}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(7)(iii)(A)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(7)(iii)(A)', 'Retraining shall be provided for all authorized and affected employees whenever there is a change in their job assignments, a change in machines, equipment or processes that present a new hazard, or when there is a change in the energy control procedures.', '2024-07-01', '2026-06-13T00:00:00Z', '01f71c2dcbafdf480f9cfefb9a8768d3e3df7b7c2b70a1cb3d8bd836bb6f84f8', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-008', 'All energy isolating devices needed to control the energy to the machine or equipment shall be physically located and operated in such a manner as to isolate the machine or equipment from energy sources.', TRUE, 'obligation', 'critical', 'observation', 'physical_condition', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(d)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(d)(3)', 'All energy isolating devices that are needed to control the energy to the machine or equipment shall be physically located and operated in such a manner as to isolate the machine or equipment from the energy source(s).', '2024-07-01', '2026-06-13T00:00:00Z', '7f42deb76105bf89e305074d1db1b2d20912f640a8a81b61a8e0964930b0aea4', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-009', 'Following the application of lockout or tagout devices to energy isolating devices, all potentially hazardous stored or residual energy shall be relieved, disconnected, restrained, and otherwise rendered safe.', TRUE, 'obligation', 'critical', 'observation', 'physical_condition', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(d)(5)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(d)(5)(i)', 'Following the application of lockout or tagout devices to energy isolating devices, all potentially hazardous stored or residual energy shall be relieved, disconnected, restrained, and otherwise rendered safe.', '2024-07-01', '2026-09-26T00:00:00Z', '75b590786439d79aa418a345ac2331d01971b926ef337b6e7a8634e086b7d96a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-010', 'Each lockout or tagout device shall be removed by the employee who applied it, except that when that employee is unavailable, removal may occur under employer direction using documented specific procedures and training that provide equivalent safety.', TRUE, 'obligation', 'high', 'observation', 'physical_condition', 'always_on', '{"condition": "Removal by another person is permitted only when the applying employee is unavailable and the documented exception procedure is followed."}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(e)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(e)(3)', 'Each lockout or tagout device shall be removed from each energy isolating device by the employee who applied the device.', '2024-07-01', '2026-06-13T00:00:00Z', '879a3c7c50a28e35bf4875b1ab2ce011bda20cf35e4fa93b561ac854059061f8', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-011', 'Whenever outside servicing personnel are engaged in covered activities, the on-site employer and the outside employer shall inform each other of their respective lockout or tagout procedures.', TRUE, 'obligation', 'medium', 'interview', 'written_program', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(f)(2)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(f)(2)(i)', 'Whenever outside servicing personnel are to be engaged in activities covered by the scope and application of this standard, the on-site employer and the outside employer shall inform each other of their respective lockout or tagout procedures.', '2024-07-01', '2026-06-13T00:00:00Z', '98eb5a957632e41275d220dc1f0c8a133b4a1cc72b1064b67b92c516e96d8480', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-22', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-012', 'The employer shall certify that the periodic inspection of the energy control procedure has been performed. The certification shall identify the machine or equipment on which the energy control procedure was being utilized, the date of the inspection, the employees included in the inspection, and the person performing the inspection.', TRUE, 'obligation', 'high', 'document_review', 'certification', 'annual_review', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(6)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(6)(ii)', 'The employer shall certify that the periodic inspections have been performed. The certification shall identify the machine or equipment on which the energy control procedure was being utilized, the date of the inspection, the employees included in the inspection, and the person performing the inspection.', '2024-07-01', '2026-09-26T00:00:00Z', 'eb285f5b1a8a3c8eac47739b0cb27c504401e245f455279a379f5d9179aad79a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-LOTO-013', 'The employer shall certify that employee training on the energy control program has been accomplished and is being kept up to date. The certification shall contain each employee''s name and the dates of training.', TRUE, 'obligation', 'high', 'document_review', 'certification', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_LOTO', '§1910.147(c)(7)(iv)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.147#p-1910.147(c)(7)(iv)', 'The employer shall certify that employee training has been accomplished and is being kept up to date. The certification shall contain each employee''s name and dates of training.', '2024-07-01', '2026-09-26T00:00:00Z', 'ba83422e6b7cea89833d3f42f908ab7544bc8da7c4f52340091bada92af71d3c', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-001', 'The employer shall develop a written plan of action regarding the implementation of employee participation.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(c)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(c)(1)', 'Employers shall develop a written plan of action regarding the implementation of the employee participation required by this paragraph.', '2024-07-01', '2026-05-04T00:00:00Z', '28d4b540429c0425a313300cab7ede87eccccbc64fdae33d8c79b994df964d67', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-002', 'The employer shall consult with employees and their representatives on the conduct and development of process hazard analyses and on other PSM elements.', TRUE, 'obligation', 'medium', 'interview', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(c)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(c)(2)', 'Employers shall consult with employees and their representatives on the conduct and development of process hazards analyses and on the development of the other elements of process safety management.', '2024-07-01', '2026-05-04T00:00:00Z', '70d08dff5c83c0a662d3bb797d8134371f76d1f901f4dfe339ec2f3f4d16390b', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-003', 'The employer shall provide employees and their representatives access to process hazard analyses and all other information required under this standard.', TRUE, 'obligation', 'medium', 'record_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(c)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(c)(3)', 'Employers shall provide to employees and their representatives access to process hazard analyses and to all other information required to be developed under this standard.', '2024-07-01', '2026-05-04T00:00:00Z', '01ed189eb5675e46d2cbe0c0c7f6a486f6a4d404fa8f7d2dd235168ccd52498e', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-004', 'The employer shall complete a compilation of written process safety information on the hazards of the highly hazardous chemicals in the process before conducting any process hazard analysis.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'chemical_handling|process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(d)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(d)', 'In accordance with the schedule set forth in paragraph (e)(1) of this section, the employer shall complete a compilation of written process safety information before conducting any process hazard analysis required by the standard. This process safety information shall include information pertaining to the hazards of the highly hazardous chemicals used or produced by the process.', '2024-07-01', '2026-09-26T00:00:00Z', '6536b0965da91ca9f3cf08ae823c7585f2ce8a6817838ffb27c7e86479a1b963', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-005', 'The employer shall document that equipment in the process complies with recognized and generally accepted good engineering practices.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'equipment_change', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance|process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(d)(3)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(d)(3)(ii)', 'The employer shall document that equipment complies with recognized and generally accepted good engineering practices.', '2024-07-01', '2026-05-04T00:00:00Z', '2a9c8e09ef444f31840cac1da5c2f59de1e12c37a5aa33fd00ac4fe1582f59f1', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-006', 'For existing equipment designed and constructed to codes no longer in general use, the employer shall determine and document that the equipment is designed, maintained, inspected, tested, and operating in a safe manner.', TRUE, 'obligation', 'high', 'physical_inspection', 'inspection_record', 'equipment_change', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(d)(3)(iii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(d)(3)(iii)', 'For existing equipment designed and constructed in accordance with codes, standards, or practices that are no longer in general use, the employer shall determine and document that the equipment is designed, maintained, inspected, tested, and operating in a safe manner.', '2024-07-01', '2026-09-26T00:00:00Z', '0e1c7856cbdd6ff6d354695d4492ebd7c7421f34250ace5c8166f676648055fd', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-007', 'The employer shall perform an initial process hazard analysis on processes covered by this standard.', TRUE, 'obligation', 'critical', 'document_review', 'written_program', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(1)', 'The employer shall perform an initial process hazard analysis (hazard evaluation) on processes covered by this standard.', '2024-07-01', '2026-05-04T00:00:00Z', '941d88c1fbe0b3647d87d872d8ab70fd4014c5e2661d789b48e0c399c53d417a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-008', 'The process hazard analysis shall address the hazards of the process, identification of previous incidents with catastrophic potential, engineering and administrative controls, consequences of control failure, facility siting, human factors, and a qualitative evaluation of safety and health effects of control failure.', TRUE, 'obligation', 'critical', 'document_review', 'written_program', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(3)', 'The process hazard analysis shall address: (i) The hazards of the process; (ii) The identification of any previous incident which had a likely potential for catastrophic consequences in the workplace; (iii) Engineering and administrative controls applicable to the hazards and their interrelationships such as appropriate application of detection methodologies to provide early warning of releases; (iv) Consequences of failure of engineering and administrative controls; (v) Facility siting; (vi) Human factors; and (vii) A qualitative evaluation of a range of the possible safety and health effects of failure of controls on employees in the workplace.', '2024-07-01', '2026-09-26T00:00:00Z', '2f318106a058b5adaef3b553ae111d5e7fb8cea1f972fe763193f4fa780b5c7e', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-009', 'The process hazard analysis shall be performed by a team with expertise in engineering and process operations, including at least one employee experienced in the process.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(4)', 'The process hazard analysis shall be performed by a team with expertise in engineering and process operations, and the team shall include at least one employee who has experience and knowledge specific to the process being evaluated.', '2024-07-01', '2026-05-04T00:00:00Z', '17c1f99dde2196ec77820d088c512e888f90022f2d4d291176700ac909d423a4', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-010', 'The employer shall establish a system to promptly address the process-hazard-analysis team''s findings and recommendations, assure timely resolution, document the resolution and actions to be taken, complete actions as soon as possible, maintain a written completion schedule, and communicate the actions to affected personnel.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(5)', 'The employer shall establish a system to promptly address the team''s findings and recommendations; assure that the recommendations are resolved in a timely manner and that the resolution is documented; document what actions are to be taken; complete actions as soon as possible; develop a written schedule of when these actions are to be completed; communicate the actions to operating, maintenance and other employees whose work assignments are in the process and who may be affected by the recommendations or actions.', '2024-07-01', '2026-09-26T00:00:00Z', 'dd12192218660279e45fa964c17c742bb616c577ee00b58913f9d2be1db641e0', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-011', 'At least every five years after the initial process hazard analysis, the employer shall update and revalidate the analysis.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'periodic_review', '{"interval_years": 5}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(6)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(6)', 'At least every five (5) years after the completion of the initial process hazard analysis, the process hazard analysis shall be updated and revalidated by a team meeting the requirements in paragraph (e)(4) of this section.', '2024-07-01', '2026-05-04T00:00:00Z', '48d5851c4f2669e122962e64c7ae46ddf6da6d7e46a42a5bccdb002f0c698733', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-012', 'The employer shall retain process hazard analyses, updates, revalidations, and resolutions of recommendations for the life of the process.', TRUE, 'obligation', 'medium', 'record_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(7)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(7)', 'Employers shall retain process hazards analyses and updates or revalidations for each process covered by this section, as well as the documented resolution of recommendations described in paragraph (e)(5) of this section for the life of the process.', '2024-07-01', '2026-09-26T00:00:00Z', '8b7e3f9021108baf6eb37ffa4825e3e3d00c01e458ff22af28da0a3f036af0e8', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-013', 'The employer shall develop and implement written operating procedures consistent with the process safety information that provide clear instructions for safely conducting activities.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(f)(1)', '§1910.119(f)(1)(i)|§1910.119(f)(1)(ii)|§1910.119(f)(1)(iii)|§1910.119(f)(1)(iv)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(f)(1)', 'The employer shall develop and implement written operating procedures that provide clear instructions for safely conducting activities involved in each covered process consistent with the process safety information.', '2024-07-01', '2026-05-04T00:00:00Z', '4c9828fab3a857322b013135a1fa4a3b8815b0c231394f7e62860df3e256cead', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-014', 'Operating procedures shall be readily accessible to employees who work in or maintain a process.', TRUE, 'obligation', 'medium', 'physical_inspection', 'procedure', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation|equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(f)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(f)(2)', 'Operating procedures shall be readily accessible to employees who work in or maintain a process.', '2024-07-01', '2026-05-04T00:00:00Z', '557177ef08f1a6638793cb41ec3c68f89015058dc5644cbf7ca5790bf4627314', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-015', 'The employer shall certify annually that the operating procedures are current and accurate.', TRUE, 'obligation', 'medium', 'document_review', 'certification', 'annual_review', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(f)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(f)(3)', 'The employer shall certify annually that these operating procedures are current and accurate.', '2024-07-01', '2026-05-04T00:00:00Z', '6b7fa238b14769d818f53437813a27b066ac620f460e5d1d2654085245f15452', 'human_reviewed', 'Eugene Sun', '2026-09-24', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-016', 'The employer shall train each employee presently involved in operating a process and each employee before operating a newly assigned process in an overview of the process and its operating procedures.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'process_assignment', '{"additional_triggers": ["onboarding_new_employee"]}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(g)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(g)(1)', 'Each employee presently involved in operating a process, and each employee before being involved in operating a newly assigned process, shall be trained in an overview of the process and in the operating procedures as specified in paragraph (f) of this section.', '2024-07-01', '2026-09-26T00:00:00Z', 'fb96ff72116a41078d5cc3c8809cbe50613fcb4d3427dd20dfe174784fae62f9', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-017', 'Refresher training shall be provided at least every three years, or more often if necessary, to each employee involved in operating a process.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'periodic_review', '{"condition": "Provide refresher training more often when necessary.", "interval_years": 3}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(g)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(g)(2)', 'Refresher training shall be provided at least every three years, and more often if necessary, to each employee involved in operating a process to assure that the employee understands and adheres to the current operating procedures of the process.', '2024-07-01', '2026-05-04T00:00:00Z', 'b6c569263dcdf1f7ebe5a3f3a118a9e6b33c9df8aa9a953fd6f0834d3ed42638', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-018', 'The employer shall ascertain and document that each employee involved in operating a process has received and understood the required training.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'onboarding_new_employee', '{"additional_triggers": ["training_refresh"], "condition": "Applies to both initial and refresher training required by §1910.119(g)."}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(g)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(g)(3)', 'The employer shall ascertain that each employee involved in operating a process has received and understood the training required by this paragraph. The employer shall prepare a record which contains the identity of the employee, the date of training, and the means used to verify that the employee understood the training.', '2024-07-01', '2026-05-04T00:00:00Z', '9d3264fe53abd1d430357a14213b8de3138a5d08fe551e98151028cf15cb2a61', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-019', 'When selecting a contractor, the employer shall obtain and evaluate information regarding the contract employer''s safety performance and programs.', TRUE, 'obligation', 'high', 'record_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(i)', 'The employer, when selecting a contractor, shall obtain and evaluate information regarding the contract employer''s safety performance and programs.', '2024-07-01', '2026-05-04T00:00:00Z', 'c18d6fed00b19c9cb5a189ac622d18ed2c8fbd021f4d18dfde2dda00dfa94735', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-020', 'The contract employer shall assure that each contract employee is trained in the work practices necessary to safely perform their job.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(3)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(3)(i)', 'The contract employer shall assure that each contract employee is trained in the work practices necessary to safely perform his/her job.', '2024-07-01', '2026-05-04T00:00:00Z', 'b9a307e0e52b609ed5eb54a84ec659b41a27219df4755f94770c0df46007528c', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-021', 'The employer shall perform a pre-startup safety review for new facilities and for modified facilities when the modification is significant enough to require a change in the process safety information.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(i)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(i)(1)', 'The employer shall perform a pre-startup safety review for new facilities and for modified facilities when the modification is significant enough to require a change in the process safety information.', '2024-07-01', '2026-05-04T00:00:00Z', '4e21e7e9b27095f0584fe05b7a0751ec3f70939d528db00cb79c099c0e4f35d0', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-022', 'Before introducing highly hazardous chemicals, the pre-startup safety review shall confirm that construction and equipment meet design specifications; procedures are adequate; for new facilities a process hazard analysis has been performed and recommendations resolved or implemented, or for modified facilities management-of-change requirements have been met; and employee training is complete.', TRUE, 'obligation', 'high', 'physical_inspection', 'inspection_record', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation|equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(i)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(i)(2)', 'The pre-startup safety review shall confirm that prior to the introduction of highly hazardous chemicals to a process:
(i) construction and equipment is in accordance with design specifications;
(ii) safety, operating, maintenance, and emergency procedures are in place and are adequate;
(iii) for new facilities, a process hazard analysis has been performed and recommendations have been resolved or implemented before startup; for modified facilities, the requirement in §1910.119(l) (management of change) has been met;
(iv) training of each employee involved in operating the process has been completed.', '2024-07-01', '2026-09-26T00:00:00Z', '55c30a2f8354b9562a497bd00c5aa36d5020823bb06f533d62679217a2957a82', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-023', 'The employer shall establish and implement written procedures to maintain the ongoing integrity of process equipment.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(j)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(j)(2)', 'The employer shall establish and implement written procedures to maintain the on-going integrity of process equipment.', '2024-07-01', '2026-05-04T00:00:00Z', 'cfbc7baa834389b4c1a0608a4451edfbf394a1e3b16eb75dff13b6e15e75ea52', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-024', 'The employer shall train each employee involved in maintaining the ongoing integrity of process equipment in an overview of the process, its hazards, and the procedures applicable to the employee''s job tasks.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(j)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(j)(3)', 'The employer shall train each employee involved in maintaining the on-going integrity of process equipment in an overview of that process and its hazards and in the procedures applicable to the employee''s job tasks.', '2024-07-01', '2026-05-04T00:00:00Z', 'b889d840c3eaec5b9887f25f72f1239c0c37d8d1f4cd10eaede8bb0e35e47f11', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-025', 'The employer shall inspect and test process equipment using recognized and generally accepted good engineering practices, at frequencies consistent with manufacturer recommendations and good engineering practices, and shall document each inspection and test performed.', TRUE, 'obligation', 'high', 'physical_inspection', 'inspection_record', 'scheduled_inspection', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(j)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(j)(4)', 'Inspections and tests shall be performed on process equipment. Inspection and testing procedures shall follow recognized and generally accepted good engineering practices. The frequency of inspections and tests of process equipment shall be consistent with applicable manufacturers'' recommendations and good engineering practices, and more frequently if determined to be necessary by prior operating experience. The employer shall document each inspection and test that has been performed on process equipment.', '2024-07-01', '2026-09-26T00:00:00Z', '7e346cdbfff19129ec2e37b6f37577c6778ea4e7c18a3074f1b46443171f0783', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-026', 'The employer shall correct deficiencies in equipment that are outside acceptable limits before further use or in a safe and timely manner when necessary means are taken to assure safe operation.', TRUE, 'obligation', 'critical', 'physical_inspection', 'inspection_record', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(j)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(j)(5)', 'The employer shall correct deficiencies in equipment that are outside acceptable limits (defined by the process safety information in paragraph (d) of this section) before further use or in a safe and timely manner when necessary means are taken to assure safe operation.', '2024-07-01', '2026-05-04T00:00:00Z', 'c059a816fd7ddd64592582c0c4961c04dcd41239ff1f398a9f1ce1add67c0b34', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-027', 'The employer shall issue a hot work permit for hot work operations conducted on or near a covered process.', TRUE, 'obligation', 'critical', 'document_review', 'permit', 'always_on', '{}', 'listed_naics_only', '32|31|23', '', 'hot_work|welding_cutting', 'any', 'federal', 'OSHA_PSM', '§1910.119(k)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(k)(1)', 'The employer shall issue a hot work permit for hot work operations conducted on or near a covered process.', '2024-07-01', '2026-05-04T00:00:00Z', '4ebc9361f2b480f8a9e4e2291b038f02f372d61c4c3f18f71a3180644a3961ea', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-028', 'The hot work permit shall document compliance with fire prevention and protection requirements, indicate the authorized dates, and identify the object on which hot work is performed; it shall be kept on file until completion of the operation.', TRUE, 'obligation', 'high', 'document_review', 'permit', 'always_on', '{}', 'listed_naics_only', '32|31|23', '', 'hot_work|welding_cutting', 'any', 'federal', 'OSHA_PSM', '§1910.119(k)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(k)(2)', 'The permit shall document that the fire prevention and protection requirements in 29 CFR 1910.252(a) have been implemented prior to beginning the hot work operations; it shall indicate the date(s) authorized for hot work; and identify the object on which hot work is to be performed.', '2024-07-01', '2026-05-04T00:00:00Z', '37df772ddf8b6bfa9f53c20a30ebca3f66030365bc6207038d003adffc300884', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-029', 'The employer shall establish and implement written procedures to manage changes to process chemicals, technology, equipment, procedures, and facilities affecting a covered process, except for replacements in kind.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'facility_change', '{}', 'listed_naics_only', '32|31', '', 'process_operation|equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(l)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(l)(1)', 'The employer shall establish and implement written procedures to manage changes (except for "replacements in kind") to process chemicals, technology, equipment, and procedures; and, changes to facilities that affect a covered process.', '2024-07-01', '2026-05-04T00:00:00Z', '5d2c0c5af01369e50e57b1d119de51a71748399a6b6fbcdd55914f6d304dd36a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-030', 'Employees involved in operating a process and maintenance and contract employees whose job tasks will be affected by a change shall be informed of and trained in the change prior to start-up.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'facility_change', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(l)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(l)(3)', 'Employees involved in operating a process and maintenance and contract employees whose job tasks will be affected by a change in the process shall be informed of, and trained in, the change prior to start-up of the process or affected part of the process.', '2024-07-01', '2026-05-04T00:00:00Z', '71acb573fe23f13b2c8faf8fdf62afb3e9d562ec1e1f746af69b073b5ca4b180', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-25', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-031', 'The employer shall investigate each incident which resulted in, or could reasonably have resulted in, a catastrophic release of a highly hazardous chemical in the workplace.', TRUE, 'obligation', 'critical', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(1)', 'The employer shall investigate each incident which resulted in, or could reasonably have resulted in a catastrophic release of highly hazardous chemical in the workplace.', '2024-07-01', '2026-05-04T00:00:00Z', '0434564e94241c14fe18837354151a6bca494ca40b28c212990178e59961600e', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-032', 'An incident investigation shall be initiated as promptly as possible, but not later than 48 hours following the incident.', TRUE, 'obligation', 'high', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(2)', 'An incident investigation shall be initiated as promptly as possible, but not later than 48 hours following the incident.', '2024-07-01', '2026-05-04T00:00:00Z', 'f626aff7cbcd45fc765be7e82fff868bf3e058b161fa385e901cecdc162e133a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-033', 'The employer shall retain incident investigation reports for five years.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(7)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(7)', 'Incident investigation reports shall be retained for five years.', '2024-07-01', '2026-05-04T00:00:00Z', 'c96fcbba434dc1c414cfd79c192f0c8041619c0474e676592af7b29eaea4335b', 'human_reviewed', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-034', 'The employer shall establish and implement an emergency action plan for the entire plant in accordance with 29 CFR 1910.38.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'always_on', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(n)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(n)', 'The employer shall establish and implement an emergency action plan for the entire plant in accordance with the provisions of 29 CFR 1910.38.', '2024-07-01', '2026-05-04T00:00:00Z', '0315699ed0b9988486dba00fa2a42ffeb73ff5310c1d09bccf36e2704c3d5b04', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-035', 'The employer shall certify that they have evaluated compliance with the provisions of this section at least every three years to verify that procedures and practices are adequate and are being followed.', TRUE, 'obligation', 'high', 'document_review', 'certification', 'audit_preparation', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(o)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(o)(1)', 'Employers shall certify that they have evaluated compliance with the provisions of this section at least every three years to verify that the procedures and practices developed under the standard are adequate and are being followed.', '2024-07-01', '2026-05-04T00:00:00Z', '04b537bd82eaf76638d86fa003b2c2d07e2adb449b45a9f5a2a3d1222b812deb', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-036', 'The compliance audit shall be conducted by at least one person knowledgeable in the process.', TRUE, 'obligation', 'medium', 'record_review', 'qualification_record', 'audit_preparation', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(o)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(o)(2)', 'The compliance audit shall be conducted by at least one person knowledgeable in the process.', '2024-07-01', '2026-05-04T00:00:00Z', '3874bbcaa92292f45b7be725e6c79cf53fc85c1cfec8912d6463d47683b3ecac', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-037', 'The employer shall promptly determine and document an appropriate response to each of the findings of the compliance audit and document that deficiencies have been corrected.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'audit_preparation', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(o)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(o)(4)', 'The employer shall promptly determine and document an appropriate response to each of the findings of the compliance audit, and document that deficiencies have been corrected.', '2024-07-01', '2026-05-04T00:00:00Z', 'dbdd72c0220d64f25277bc768699e29cfed7a213feafed1e33d129c8950a5c17', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-038', 'The employer shall retain the two most recent compliance audit reports.', TRUE, 'obligation', 'low', 'record_review', 'retention_record', 'audit_preparation', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(o)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(o)(5)', 'Employers shall retain the two (2) most recent compliance audit reports.', '2024-07-01', '2026-05-04T00:00:00Z', '31efd777605f783fe4f42eb78c4b602a9991d8b63ec0cc5f7cfe2939df37586e', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-039', 'The employer shall use one or more recognized methodologies (such as What-If, Checklist, HAZOP, FMEA, or Fault Tree Analysis) appropriate to determine and evaluate the hazards of the process being analyzed.', TRUE, 'obligation', 'high', 'document_review', 'written_program', 'new_process_startup', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(e)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(e)(2)', 'The employer shall use one or more of the following methodologies that are appropriate to determine and evaluate the hazards of the process being analyzed. What-If; Checklist; What-If/Checklist; Hazard and Operability Study (HAZOP); Failure Mode and Effects Analysis (FMEA); Fault Tree Analysis; or An appropriate equivalent methodology.', '2024-07-01', '2026-06-13T00:00:00Z', '16269f40f589bf5724c6ea41c5cfec4120d5558e67c33b20e7ea36115fc23d42', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-040', 'The employer shall periodically evaluate the performance of contract employers in fulfilling their safety obligations.', TRUE, 'obligation', 'medium', 'record_review', 'performance_evaluation', 'annual_review', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(v)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(v)', 'The employer shall periodically evaluate the performance of contract employers in fulfilling their obligations as specified in paragraph (h)(3) of this section.', '2024-07-01', '2026-06-13T00:00:00Z', '5e8a5d63810d93b29135de967770054fb088e8e2105167e6cf509248a7786bae', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-041', 'In the construction of new plants and equipment, the employer shall assure that equipment as it is fabricated is suitable for the process application for which it will be used.', TRUE, 'obligation', 'high', 'physical_inspection', 'inspection_record', 'equipment_change', '{}', 'listed_naics_only', '32|31', '', 'equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(j)(6)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(j)(6)(i)', 'In the construction of new plants and equipment, the employer shall assure that equipment as it is fabricated is suitable for the process application for which they will be used.', '2024-07-01', '2026-06-13T00:00:00Z', 'a486673a4d5b4bb1bf6701167f41fd4febb2e7dd083f5152fb4b44ac01b95e68', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-042', 'The management of change procedures shall assure that the technical basis, impact on safety and health, modifications to operating procedures, necessary time period, and authorization requirements are addressed prior to any change.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'facility_change', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(l)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(l)(2)', 'The procedures shall assure that the following considerations are addressed prior to any change: The technical basis for the proposed change; Impact of change on safety and health; Modifications to operating procedures; Necessary time period for the change; and, Authorization requirements for the proposed change.', '2024-07-01', '2026-06-13T00:00:00Z', '12279da2f5768def1400885c9759c3db787cd3a9bc45fcef824d64951596aa64', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-043', 'If a change results in a change in the process safety information, such information shall be updated accordingly.', TRUE, 'obligation', 'medium', 'document_review', 'written_program', 'facility_change', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(l)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(l)(4)', 'If a change covered by this paragraph results in a change in the process safety information required by paragraph (d) of this section, such information shall be updated accordingly.', '2024-07-01', '2026-06-13T00:00:00Z', 'af3dd7a54d92b0718ba72df6d1d698d2346d44f3652f2efeb8e84b22d518b2f3', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-044', 'The employer shall establish a system to promptly address and resolve the incident report findings and recommendations, and resolutions and corrective actions shall be documented.', TRUE, 'obligation', 'high', 'document_review', 'incident_record', 'incident_occurrence', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(5)', 'The employer shall establish a system to promptly address and resolve the incident report findings and recommendations. Resolutions and corrective actions shall be documented.', '2024-07-01', '2026-06-13T00:00:00Z', '8e0a8b55b99f0cfaa03b1498f465c7f288e4129f6d8a47a28b4ca8015122a7bd', 'human_reviewed', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-045', 'The incident investigation report shall be reviewed with all affected personnel whose job tasks are relevant to the incident findings, including contract employees where applicable.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'incident_occurrence', '{}', 'listed_naics_only', '32|31', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(6)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(6)', 'The report shall be reviewed with all affected personnel whose job tasks are relevant to the incident findings including contract employees where applicable.', '2024-07-01', '2026-06-13T00:00:00Z', 'cf207823e4110a771a05676c110c6f33632fc2a13ec12288edd8d7f7be38fed6', 'human_reviewed', 'Eugene Sun', '2026-09-26', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-046', 'The emergency action plan shall include procedures for handling small releases.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'chemical_handling|process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(n)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(n)', 'In addition, the emergency action plan shall include procedures for handling small releases.', '2024-07-01', '2026-09-26T00:00:00Z', '8ccff1a35f06a420c44c3cd3f37b2a605e66e452037c1f09d08da520900de471', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-047', 'The employer shall review operating procedures as often as necessary and update them to reflect current operating practice and relevant changes to process chemicals, technology, equipment, and facilities.', TRUE, 'obligation', 'medium', 'document_review', 'procedure', 'facility_change', '{}', 'listed_naics_only', '31|32', '', 'process_operation|equipment_maintenance', 'any', 'federal', 'OSHA_PSM', '§1910.119(f)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(f)(3)', '(3) The operating procedures shall be reviewed as often as necessary to assure that they reflect current operating practice, including changes that result from changes in process chemicals, technology, and equipment, and changes to facilities.', '2024-07-01', '2026-09-26T00:00:00Z', '106b9bfa3e836875d2de1dad12739218ff5f30e7e247c184b23973e99d325a65', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-048', 'The employer shall inform contract employers of known potential fire, explosion, or toxic-release hazards related to the contractor''s work and the covered process.', TRUE, 'obligation', 'high', 'interview', 'written_program', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(ii)', '(ii) The employer shall inform contract employers of the known potential fire, explosion, or toxic release hazards related to the contractor''s work and the process.', '2024-07-01', '2026-09-26T00:00:00Z', 'bb82012b672e54d852e03705dcaf07cfd8316fba58f9805abbd68c0bfda779e6', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-049', 'The employer shall explain to contract employers the applicable provisions of the emergency action plan required by §1910.119(n).', TRUE, 'obligation', 'high', 'interview', 'written_program', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(iii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(iii)', '(iii) The employer shall explain to contract employers the applicable provisions of the emergency action plan required by paragraph (n) of this section.', '2024-07-01', '2026-09-26T00:00:00Z', '97ecffd4f6509f8c10a57d5b00287b6dd8a04817b61d5ff3007b4aee6369d59a', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-050', 'The employer shall develop and implement safe work practices, consistent with §1910.119(f)(4), to control the entrance, presence, and exit of contract employers and contract employees in covered process areas.', TRUE, 'obligation', 'high', 'document_review', 'procedure', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(iv)', '§1910.119(f)(4)', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(iv)', '(iv) The employer shall develop and implement safe work practices consistent with paragraph (f)(4) of this section, to control the entrance, presence and exit of contract employers and contract employees in covered process areas.', '2024-07-01', '2026-09-26T00:00:00Z', '46f0b23f784402e8c569529b1eef470e31b9a54a5b40bebdac6479cc5ec24d82', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-051', 'The employer shall maintain a contract-employee injury and illness log related to contractor work in process areas.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(2)(vi)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(2)(vi)', '(vi) The employer shall maintain a contract employee injury and illness log related to the contractor''s work in process areas.', '2024-07-01', '2026-09-26T00:00:00Z', 'd1f3af8c050c238d58832c108cc6ff7011081a2b6b1ac46360a8f040e5845f39', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-052', 'The contract employer shall ensure each contract employee is instructed in known potential fire, explosion, or toxic-release hazards related to the employee''s job and the process, and in applicable emergency-action-plan provisions.', TRUE, 'obligation', 'high', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(3)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(3)(ii)', '(ii) The contract employer shall assure that each contract employee is instructed in the known potential fire, explosion, or toxic release hazards related to his/her job and the process, and the applicable provisions of the emergency action plan.', '2024-07-01', '2026-09-26T00:00:00Z', '1c13186987806ecae9dcc63d6e9623913a725cf84c557b5ecbba04967571f98c', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-053', 'The contract employer shall document that each contract employee received and understood required training, including the employee''s identity, training date, and the method used to verify understanding.', TRUE, 'obligation', 'medium', 'record_review', 'training_record', 'onboarding_new_employee', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(3)(iii)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(3)(iii)', '(iii) The contract employer shall document that each contract employee has received and understood the training required by this paragraph. The contract employer shall prepare a record which contains the identity of the contract employee, the date of training, and the means used to verify that the employee understood the training.', '2024-07-01', '2026-09-26T00:00:00Z', '6055a9b24bfa2b160bbec958b8dd423b41d28fcd55f881872c82d591cc52f239', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-054', 'The contract employer shall ensure each contract employee follows facility safety rules, including the safe work practices required by §1910.119(f)(4).', TRUE, 'obligation', 'high', 'observation', 'physical_condition', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(3)(iv)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(3)(iv)', '(iv) The contract employer shall assure that each contract employee follows the safety rules of the facility including the safe work practices required by paragraph (f)(4) of this section.', '2024-07-01', '2026-09-26T00:00:00Z', '81848d5aa3b67452ea2f32ac5c0c50e32410034224b6e763664942e881f3e593', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-055', 'The contract employer shall advise the host employer of unique hazards presented by the contract work and hazards discovered during that work.', TRUE, 'obligation', 'high', 'interview', 'written_program', 'always_on', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(h)(3)(v)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(h)(3)(v)', '(v) The contract employer shall advise the employer of any unique hazards presented by the contract employer''s work, or of any hazards found by the contract employer''s work.', '2024-07-01', '2026-09-26T00:00:00Z', 'fc56e75bd3c9c285c067ac15c4de5b9e7ec925d3b5d118852b9579b8c2720992', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-056', 'At the conclusion of an incident investigation, the employer shall prepare a report that includes, at a minimum, the date of the incident, the date the investigation began, a description of the incident, the factors that contributed to the incident, and any recommendations resulting from the investigation.', TRUE, 'obligation', 'high', 'document_review', 'incident_record', 'incident_occurrence', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(m)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(m)(4)', 'A report shall be prepared at the conclusion of the investigation which includes at a minimum: (i) Date of incident; (ii) Date investigation began; (iii) A description of the incident; (iv) The factors that contributed to the incident; and, (v) Any recommendations resulting from the investigation.', '2024-07-01', '2026-09-26T00:00:00Z', 'cb973b0726a9e0ab44889487ec922dace241e1bf7503f72f0cdf6863fd2379fa', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-PSM-057', 'The employer shall develop a report of the findings of the compliance audit conducted under this section.', TRUE, 'obligation', 'high', 'document_review', 'certification', 'audit_preparation', '{}', 'listed_naics_only', '31|32', '', 'process_operation', 'any', 'federal', 'OSHA_PSM', '§1910.119(o)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1910/section-1910.119#p-1910.119(o)(3)', 'A report of the findings of the audit shall be developed.', '2024-07-01', '2026-09-26T00:00:00Z', '4c1062f09510bda2ae2292d5b33088ce4e7dae53f27f815486513f1941271d67', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-001', 'Each employer required to keep records must record each fatality, injury, and illness that is work-related, is a new case, and meets one or more of the general recording criteria.', TRUE, 'obligation', 'high', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.4(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.4(a)', 'Each employer required by this part to keep records of fatalities, injuries, and illnesses must record each fatality, injury and illness that is work-related; is a new case; and meets one or more of the general recording criteria.', '2024-07-01', '2026-05-04T00:00:00Z', 'e90b093f5bdfac90f6722a868c68bf75ce491be1c3fd3455f73efc60a60658cc', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-002', 'The employer must consider an injury or illness to meet the general recording criteria if it results in death, days away from work, restricted work, transfer to another job, medical treatment beyond first aid, loss of consciousness, or diagnosis of a significant injury by a health care professional.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.7(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.7(a)', 'You must consider an injury or illness to meet the general recording criteria, and therefore to be recordable, if it results in any of the following: death, days away from work, restricted work or transfer to another job, medical treatment beyond first aid, or loss of consciousness.', '2024-07-01', '2026-05-04T00:00:00Z', 'b33bff6f08d328571c45bbccbd758b9a2f11490c75ed05c6a7e8cbb40540ae2e', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-003', 'The employer must enter each recordable injury or illness on the OSHA 300 Log and 301 Incident Report within seven calendar days of receiving information that a recordable injury or illness has occurred.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.29(b)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.29(b)(3)', 'You must enter each recordable injury or illness on the OSHA 300 Log and 301 Incident Report within seven (7) calendar days of receiving information that a recordable injury or illness has occurred.', '2024-07-01', '2026-05-04T00:00:00Z', '5bbc409d9bd0ac324b7a4ffacde89ad311a4d80312ea43edd18fdadc9f03662f', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-004', 'At the end of each calendar year, the employer must review the OSHA 300 Log for completeness and accuracy and correct identified deficiencies.', TRUE, 'obligation', 'medium', 'document_review', 'incident_record', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(a)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(a)(1)', '(1) Review the OSHA 300 Log to verify that the entries are complete and accurate, and correct any deficiencies identified;', '2024-07-01', '2026-09-26T00:00:00Z', 'ec72b3a8d0a071ac3a251b79afd13008833ef1b73962135dd3b708fad7acf191', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-005', 'The employer must post the annual summary in a conspicuous place where notices to employees are customarily posted, and ensure it is not altered, defaced, or covered by other material.', TRUE, 'obligation', 'low', 'physical_inspection', 'physical_condition', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(b)(5)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(b)(5)', 'You must post a copy of the annual summary in each establishment in a conspicuous place or places where notices to employees are customarily posted. You must ensure that the posted annual summary is not altered, defaced or covered by other material.
INSERT INTO requirement VALUES ('OSHA-REC-006', 'Within eight hours after the death of any employee from a work-related incident, the employer must report the fatality to OSHA.', TRUE, 'obligation', 'critical', 'record_review', 'manifest_or_form', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.39(a)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.39(a)(1)', 'Within eight (8) hours after the death of any employee as a result of a work-related incident, you must report the fatality to OSHA.', '2024-07-01', '2026-05-04T00:00:00Z', '3b05f2d8bdea1308e829827c77f2e529209874afb1bfeb8529ae4902276142f0', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-007', 'Within twenty-four hours after an employee''s work-related in-patient hospitalization, amputation, or loss of an eye, the employer must report the event to OSHA.', TRUE, 'obligation', 'high', 'record_review', 'manifest_or_form', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.39(a)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.39(a)(2)', 'Within twenty-four (24) hours after the in-patient hospitalization of one or more employees or an employee''s amputation or an employee''s loss of an eye, as a result of a work-related incident, you must report the event to OSHA.', '2024-07-01', '2026-05-04T00:00:00Z', '5a8ccad507b476e556012db1f8d4b7d4abe4c8bd8d92e98c6e635d225be26745', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-008', 'The employer must retain the OSHA 300 Log, the privacy case list, the annual summary, and the 301 Incident Report forms for five years following the end of the calendar year that the records cover.', TRUE, 'obligation', 'low', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.33(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.33(a)', 'You must save the OSHA 300 Log, the privacy case list (if one exists), the annual summary, and the OSHA 301 Incident Report forms for five (5) years following the end of the calendar year that these records cover.', '2024-07-01', '2026-05-04T00:00:00Z', '0ca205ec63d8d5acbdb4eab45a85b64c1ce0853b826baa104095601e338bf6ce', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-009', 'If a case is a privacy concern case, the employer may not enter the employee''s name on the OSHA 300 Log and shall instead enter ''privacy case'' in the space normally used for the name.', TRUE, 'prohibition', 'medium', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.29(b)(6)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.29(b)(6)', 'If you have a "privacy concern case," you may not enter the employee''s name on the OSHA 300 Log. Instead, enter "privacy case" in the space normally used for the employee''s name.', '2024-07-01', '2026-06-13T00:00:00Z', 'ef49bf095e92bbb41bdd641ec9bd9f5160e8d3b620c8d651288c9dd46af28e58', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-010', 'The employer must keep a separate OSHA 300 Log for each establishment that is expected to be in operation for one year or longer.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.30(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.30(a)', 'You must keep a separate OSHA 300 Log for each establishment that is expected to be in operation for one year or longer.', '2024-07-01', '2026-06-13T00:00:00Z', '89ae649e50b77b270edd5f8fa1b31c18f5f3f95543dbab1b77de65953ed54c9d', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-011', 'The employer must record the recordable injuries and illnesses of employees on its payroll and workers it supervises day to day; sole proprietors and partners are not considered employees for Part 1904 recordkeeping purposes.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'incident_occurrence', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.31(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.31(a)', 'You must record on the OSHA 300 Log the recordable injuries and illnesses of all employees on your payroll, whether they are labor, executive, hourly, salary, part-time, seasonal, or migrant workers. You also must record the recordable injuries and illnesses that occur to employees who are not on your payroll if you supervise these employees on a day-to-day basis. If your business is organized as a sole proprietorship or partnership, the owner or partners are not considered employees for recordkeeping purposes.', '2024-07-01', '2026-09-26T00:00:00Z', '11229654350ee3aec908c542d35865f46cf8cec107386c38aa855370bce2fea7', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-012', 'During the five-year storage period, the employer must update stored OSHA 300 Logs for newly discovered recordable cases and classification changes; when a description or outcome changes, the original entry must be removed or lined out and replaced with the new information.', TRUE, 'obligation', 'low', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.33(b)(1)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.33(b)(1)', 'Yes, during the storage period, you must update your stored OSHA 300 Logs to include newly discovered recordable injuries or illnesses and to show any changes that have occurred in the classification of previously recorded injuries and illnesses. If the description or outcome of a case changes, you must remove or line out the original entry and enter the new information.', '2024-07-01', '2026-09-26T00:00:00Z', 'ce587421d96ff6a57aa85070c90c6265d9fbdb9d297ebc019991f8e00030f3d0', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-013', 'The employer must establish a reasonable procedure for employees to report work-related injuries and illnesses promptly and accurately; the procedure must not deter or discourage accurate reporting.', TRUE, 'obligation', 'high', 'interview', 'procedure', 'onboarding_new_employee', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(1)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(1)(i)', '(i) You must establish a reasonable procedure for employees to report work-related injuries and illnesses promptly and accurately. A procedure is not reasonable if it would deter or discourage a reasonable employee from accurately reporting a workplace injury or illness;', '2024-07-01', '2026-09-26T00:00:00Z', '088e4d769fe227c2fc68b75875c6710f64e188669417e0f8bbb71915af5475a4', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-014', 'The employer must not discharge or in any manner discriminate against any employee for reporting a work-related injury or illness.', TRUE, 'prohibition', 'critical', 'interview', 'complaint_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(1)(iv)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(1)(iv)', 'You must not discharge or in any manner discriminate against any employee for reporting a work-related injury or illness.', '2024-07-01', '2026-06-13T00:00:00Z', '2fa85a9036ce7d995e288350e3d6207adcee29fd2cde6638cf4c070d3da86809', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-015', 'When an employee, former employee, personal representative, or authorized employee representative requests relevant OSHA 300 Logs for an establishment where the employee worked, the employer must provide copies by the end of the next business day.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(2)(iii)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(2)(iii)', '(iii) If an employee or representative asks for access to the OSHA 300 Log, when do I have to provide it? When an employee, former employee, personal representative, or authorized employee representative asks for copies of your current or stored OSHA 300 Log(s) for an establishment the employee or former employee has worked in, you must give the requester a copy of the relevant OSHA 300 Log(s) by the end of the next business day.', '2024-07-01', '2026-09-26T00:00:00Z', '0f65e1edc1dc59b3ac5db390bb2d326cf8aa6f5ee8a22c6b1a53f87962daa739', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-016', 'When an authorized government representative asks for the records kept under Part 1904, the employer must provide copies within four business hours.', TRUE, 'obligation', 'high', 'record_review', 'incident_record', 'audit_preparation', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.40(a)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.40(a)', 'When an authorized government representative asks for the records you keep under part 1904, you must provide copies of the records within four (4) business hours.', '2024-07-01', '2026-06-13T00:00:00Z', '93c406a6849e0e0420c3d64dd119a1b2530871e8914325dac77f0306677310ae', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-017', 'Establishments with 250 or more employees that are required to keep Part 1904 records must electronically submit information from the OSHA Form 300A annually.', TRUE, 'obligation', 'medium', 'record_review', 'manifest_or_form', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', '250+', 'federal', 'OSHA_RECORDKEEPING', '§1904.41(a)(1)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.41(a)(1)(ii)', 'If your establishment had 250 or more employees at any time during the previous calendar year, and this part requires your establishment to keep records, then you must electronically submit information from OSHA Form 300A Summary of Work-Related Injuries and Illnesses to OSHA or OSHA''s designee.', '2024-07-01', '2026-06-13T00:00:00Z', '46d094f88ef13d3a7d8bdc9ad1223890d509e2708201c0fa3003224fb82d40b5', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-23', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-018', 'At the end of each calendar year, the employer must create an annual summary of injuries and illnesses recorded on the OSHA 300 Log.', TRUE, 'obligation', 'medium', 'document_review', 'manifest_or_form', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(a)(2)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(a)(2)', '(2) Create an annual summary of injuries and illnesses recorded on the OSHA 300 Log;', '2024-07-01', '2026-09-26T00:00:00Z', 'e978900353e71a0bb1f5fdae483624c656efcb345fa22cbec512c063731cf47f', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-019', 'At the end of each calendar year, the employer must certify the annual injury and illness summary.', TRUE, 'obligation', 'medium', 'document_review', 'certification', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(a)(3)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(a)(3)', '(3) Certify the summary; and', '2024-07-01', '2026-09-26T00:00:00Z', '3c59c0165f27b3665dd38141d9bdfce733f080e6042e51cdd16474cfa7eb4807', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-020', 'At the end of each calendar year, the employer must post the annual injury and illness summary.', TRUE, 'obligation', 'low', 'physical_inspection', 'physical_condition', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(a)(4)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(a)(4)', '(4) Post the annual summary.', '2024-07-01', '2026-09-26T00:00:00Z', 'b0c8680d18f0bb018a24c727f89dbb65d511d2821370f1a8ee6ce9749420f616', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-021', 'For privacy concern cases, the employer must maintain a separate confidential list of case numbers and employee names so cases can be updated and information supplied to the government on request.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.29(b)(6)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.29(b)(6)', 'You must keep a separate, confidential list of the case numbers and employee names for your privacy concern cases so you can update the cases and provide the information to the government if asked to do so.', '2024-07-01', '2026-09-26T00:00:00Z', '31db90fd6157de60461e7f56d0ea03f8eb8bbef9102043233e5ca79ac2b4c236', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-022', 'The employer must inform each employee of its procedure for reporting work-related injuries and illnesses.', TRUE, 'obligation', 'high', 'interview', 'training_record', 'onboarding_new_employee', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(1)(ii)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(1)(ii)', '(ii) You must inform each employee of your procedure for reporting work-related injuries and illnesses;', '2024-07-01', '2026-09-26T00:00:00Z', '309b564c08a29f423701d4ac862e243fce09ca107cfec91b1b48c32ba37db415', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-023', 'When an employee, former employee, or personal representative requests the OSHA 301 Incident Report describing that employee''s injury or illness, the employer must provide the report by the end of the next business day.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(2)(v)(A)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(2)(v)(A)', '(A) When an employee, former employee, or personal representative asks for a copy of the OSHA 301 Incident Report describing an injury or illness to that employee or former employee, you must give the requester a copy of the OSHA 301 Incident Report containing that information by the end of the next business day.', '2024-07-01', '2026-09-26T00:00:00Z', '78b1ac8a2f1220f8ba202f2937f3acaa23a594d027a57d60059e3b6f4e8f40b7', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-024', 'When an authorized employee representative requests OSHA 301 Incident Reports for a represented establishment, the employer must provide the permitted ''Tell us about the case'' information within seven calendar days and remove all other information.', TRUE, 'obligation', 'medium', 'record_review', 'incident_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.35(b)(2)(v)(B)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.35(b)(2)(v)(B)', '(B) When an authorized employee representative asks for copies of the OSHA 301 Incident Reports for an establishment where the agent represents employees under a collective bargaining agreement, you must give copies of those forms to the authorized employee representative within 7 calendar days. You are only required to give the authorized employee representative information from the OSHA 301 Incident Report section titled "Tell us about the case." You must remove all other information from the copy of the OSHA 301 Incident Report or the equivalent substitute form that you give to the authorized employee representative.', '2024-07-01', '2026-09-26T00:00:00Z', '6f7dc71377cbfd9ca52d04aa299c7a6148911b25d32bce6254096eb68a5704ed', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-025', 'The employer must post the annual summary no later than February 1 following the covered year and keep it posted through April 30.', TRUE, 'obligation', 'low', 'physical_inspection', 'physical_condition', 'annual_review', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.32(b)(6)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.32(b)(6)', '(6) When do I have to post the annual summary? You must post the summary no later than February 1 of the year following the year covered by the records and keep the posting in place until April 30.', '2024-07-01', '2026-09-26T00:00:00Z', '0a591cc17bb3d4fd87bcb705fa8e58d5062044f54e91877303a9b213fbd3bfc2', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-026', 'An establishment with 20 to 249 employees in an industry listed in Appendix A to Subpart E must electronically submit OSHA Form 300A information annually by the specified reporting date.', TRUE, 'obligation', 'medium', 'record_review', 'manifest_or_form', 'annual_review', '{}', 'listed_naics_only', '', 'Industry listed in Appendix A to Subpart E of 29 CFR Part 1904.', 'process_operation', '20-249', 'federal', 'OSHA_RECORDKEEPING', '§1904.41(a)(1)(i)', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.41(a)(1)(i)', '(i) If your establishment had 20-249 employees at any time during the previous calendar year, and your establishment is classified in an industry listed in appendix A to subpart E of this part, then you must electronically submit information from OSHA Form 300A Summary of Work-Related Injuries and Illnesses to OSHA or OSHA''s designee. You must submit the information once a year, no later than the date listed in paragraph (c) of this section of the year after the calendar year covered by the form.', '2024-07-01', '2026-09-26T00:00:00Z', 'c8e12cf10347142f7b91033ed5f3791a60009dd6283d91266937d2c084d307ae', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
INSERT INTO requirement VALUES ('OSHA-REC-027', 'The employer must not discharge or in any manner discriminate against an employee for reporting a work-related fatality, injury, or illness; for filing a safety and health complaint; for requesting access to Part 1904 injury and illness records; or for otherwise exercising any right afforded by the OSH Act.', TRUE, 'prohibition', 'high', 'interview', 'complaint_record', 'always_on', '{}', 'all_covered_industries', '', '', 'process_operation', 'any', 'federal', 'OSHA_RECORDKEEPING', '§1904.36', '', 'https://www.ecfr.gov/current/title-29/part-1904#p-1904.36', 'In addition to Sec.1904.35, section 11(c) of the OSH Act also prohibits you from discriminating against an employee for reporting a work-related fatality, injury, or illness. That provision of the Act also protects the employee who files a safety and health complaint, asks for access to the part 1904 records, or otherwise exercises any rights afforded by the OSH Act.', '2024-07-01', '2026-09-26T00:00:00Z', '62ad83c0ddc68797bb61a0cfdd6fc50d34eaea233b7de77063297ef916c2c0e5', 'ai_assisted_with_human_review', 'Eugene Sun', '2026-09-27', 'implemented_from_human_verification');
